3: import { useEffect, useState, useMemo, useRef } from "react";
4: import * as THREE from "three";
5: import { Box, Sphere } from "@react-three/drei";
6: 
7: import Workbench3D from "@/features/interactive-activities/shared/components/Workbench3D";
8: import { useDraggable3D } from "@/features/interactive-activities/shared/hooks/useDraggable3D";
9: import { useSnapZone } from "@/features/interactive-activities/shared/hooks/useSnapZone";
10: import { useSnapStore } from "@/features/interactive-activities/shared/stores/snap-store";
11: import { useActivityStore } from "@/features/interactive-activities/shared/stores/activity-store";
12: import InteractionHint from "@/features/interactive-activities/shared/components/InteractionHint";
13: import SubmitBar from "@/features/interactive-activities/shared/components/SubmitBar";
