15: /**
16:  * 3D Scene Content
17:  */
18: function SandboxSceneContent() {
19:   const { setScore, updateStateCheck } = useActivityStore();
20:   const getClosestZone = useSnapStore((state) => state.getClosestZone);
21: 
22:   // Box state
23:   const [boxPosition, setBoxPosition] = useState<THREE.Vector3>(new THREE.Vector3(-3, 0.5, 0));
24:   const [isSnapped, setIsSnapped] = useState(false);
25: 
26:   // Define a snap socket target
27:   const targetPosition: [number, number, number] = [3, 0.5, 0];
28:   const { position: socketPos } = useSnapZone({
29:     id: "target-socket",
30:     position: targetPosition,
31:     radius: 1.5,
32:   });
33: 
34:   // Make the box draggable
35:   const { ref: dragRef, isDragging, handlers } = useDraggable3D({
36:     planeNormal: [0, 1, 0],
37:     disabled: isSnapped,
38:     onDragEnd: (finalPosition) => {
39:       // Check if we dropped near a socket
40:       const closest = getClosestZone(finalPosition, 1.5);
41:       
42:       if (closest && closest.id === "target-socket") {
43:         // Snap!
44:         setBoxPosition(closest.position.clone());
45:         setIsSnapped(true);
46:         setScore(100);
47:         updateStateCheck("box_snapped", true);
48:       } else {
49:         setBoxPosition(finalPosition.clone());
50:       }
51:     },
52:   });
53: 
54:   // Update visual position of box (useDraggable updates the ref directly while dragging,
55:   // but we need to resync if we snap programmatically).
56:   useEffect(() => {
57:     if (dragRef.current && !isDragging) {
58:       dragRef.current.position.copy(boxPosition);
59:     }
60:   }, [boxPosition, dragRef, isDragging]);
61: 
62:   return (
63:     <>
64:       {/* Target Socket Marker */}
65:       <Sphere args={[0.3, 16, 16]} position={targetPosition}>
66:         <meshStandardMaterial color="#cbd5e1" wireframe />
67:       </Sphere>
68:       
69:       <InteractionHint 
70:         position={targetPosition} 
71:         label="Drag the box here" 
72:         size={[1.5, 1.5, 1.5]}
73:         visible={!isSnapped} 
74:       />
75: 
76:       {/* Draggable Box */}
77:       <Box 
78:         ref={dragRef as any}
79:         args={[1, 1, 1]} 
80:         position={[-3, 0.5, 0]}
81:         {...handlers}
82:       >
83:         <meshStandardMaterial 
84:           color={isSnapped ? "#10b981" : (isDragging ? "#f59e0b" : "#3b82f6")} 
85:         />
86:       </Box>
87:     </>
88:   );
89: }
90: 
91: /**
92:  * Sandbox Page — A dev-only route for testing the 3D Engine layer.
93:  */
94: export default function SandboxPage() {
95:   const { startTimer, resetActivity } = useActivityStore();
96:   const startTimeRef = useRef(new Date().toISOString());
97:   
98:   // Dummy data for Sprint 0 Submission API
99:   // In a real activity, this comes from the route params or session
100:   const dummyStudentId = "dev-student-123";
101:   const dummyAssignmentId = "dev-template-123";
102: 
103:   useEffect(() => {
104:     resetActivity();
105:     startTimer();
106:     return () => resetActivity();
107:   }, [resetActivity, startTimer]);
108: 
109:   return (
110:     <div className="flex flex-col h-full w-full bg-gray-50 relative">
111:       {/* Dev Warning Banner */}
112:       <div className="absolute top-0 left-0 w-full bg-amber-500 text-white text-xs font-bold text-center py-1 z-20 shadow-md">
113:         DEV SANDBOX — Sprint 1 Engine Test (Do Not Deploy)
114:       </div>
115: 
116:       {/* 3D Viewport */}
117:       <div className="flex-1 w-full h-full">
118:         <Workbench3D>
119:           <SandboxSceneContent />
120:         </Workbench3D>
121:       </div>
122: 
123:       {/* 2D Overlay UI */}
124:       <SubmitBar 
125:         activityType="pc-build" // Dummy type from allowed schema enum
126:         assignmentId={dummyAssignmentId}
127:         studentId={dummyStudentId}
128:         variantSeed="dev-seed"
129:         startedAt={startTimeRef.current}
130:         maxScore={100}
131:       />
132:     </div>
133:   );
134: }
