1: import { db } from "@/lib/db";
2: import { getInstituteTheme } from "@/lib/get-institute-theme";
3: import { getSession } from "@/lib/auth-session";
4: import { redirect } from "next/navigation";
5: import CourseHeader from "@/components/courses/CourseHeader";
6: import CourseTabs from "@/components/courses/CourseTabs";
7: 
8: type LayoutProps = {
9:   children: React.ReactNode;
10:   params: Promise<{ institute: string; courseId: string }>;
11: };
12: 
13: export default async function CourseInteriorLayout({
14:   children,
15:   params,
16: }: LayoutProps) {
17:   const { institute, courseId } = await params;
18:   const session = await getSession();
19: 
20:   if (!session) {
21:     redirect(`/login?institute=${institute}`);
22:   }
23: 
24:   const theme = getInstituteTheme(institute);
25: 
26:   const course = await db.course.findUnique({
27:     where: { id: courseId },
28:     include: {
29:       instructor: { select: { name: true } },
30:       _count: {
31:         select: {
32:           enrollments: { where: { status: "PENDING" } },
33:         },
34:       },
35:     },
36:   });
37: 
38:   if (!course) {
39:     redirect(`/${institute}/courses`);
40:   }
41: 
42:   // Access control: user must be instructor, enrolled student, or admin
43:   const userRole = session.user.role.toUpperCase();
44:   const isInstructor = course.instructorId === session.user.id;
45:   const isAdmin = userRole === "ADMIN";
46: 
47:   if (!isInstructor && !isAdmin) {
48:     // Check if student is enrolled
49:     const enrollment = await db.enrollment.findUnique({
50:       where: {
51:         courseId_studentId: {
52:           courseId: course.id,
53:           studentId: session.user.id,
54:         },
55:       },
56:     });
57: 
58:     if (!enrollment || enrollment.status !== "APPROVED") {
59:       redirect(`/${institute}/courses`);
60:     }
61:   }
62: 
63:   const showPendingCount =
64:     isInstructor || isAdmin ? course._count.enrollments : 0;
65: 
66:   const pendingWorkCount =
67:     isInstructor || isAdmin
68:       ? await db.studentSubmission.count({
69:           where: {
70:             syllabusItem: { courseId: course.id },
71:             status: "SUBMITTED",
72:             OR: [{ grade: null }, { isReturned: false }],
73:           },
74:         })
75:       : 0;
76: 
77:   return (
78:     <div className="-m-4 lg:-m-8">
79:       <div className="px-4 pt-4 md:px-8 md:pt-6">
80:         <CourseHeader
81:           course={course}
82:           theme={theme}
83:           pendingWorkCount={pendingWorkCount}
84:           isInstructor={isInstructor || isAdmin}
85:           instituteCode={institute}
86:           courseId={courseId}
87:         />
88:       </div>
89:       <div className="mt-4">
90:         <CourseTabs
91:           courseId={courseId}
92:           instituteCode={institute}
93:           theme={theme}
94:           pendingCount={showPendingCount}
95:           pendingWorkCount={pendingWorkCount}
96:           isInstructor={isInstructor || isAdmin}
97:         />
98:       </div>
99:       <div className="px-4 py-6 md:px-8">{children}</div>
100:     </div>
101:   );
102: }
