1: import { redirect } from "next/navigation";
2: import { getSession } from "@/lib/auth-session";
3: import { getInstituteTheme } from "@/lib/get-institute-theme";
4: import { isEligibleForActivities } from "@/lib/activity-eligibility";
5: import { isEligibleForKnowledgeExchange } from "@/lib/kx-eligibility";
6: import { db } from "@/lib/db";
7: import { processLoginReward } from "@/lib/gamification/login-rewards";
8: import DashboardLayout from "@/components/layout/DashboardLayout";
9: 
10: export const dynamic = "force-dynamic";
11: 
12: export default async function InstituteLayout({ 
13:   children, 
14:   params 
15: }: { 
16:   children: React.ReactNode,
17:   params: Promise<{ institute: string }>
18: }) {
19:   const { institute } = await params;
20:   const session = await getSession();
21: 
22:   if (!session) {
23:     redirect(`/login?institute=${institute}`);
24:   }
25: 
26:   // Enforce institute scoping: students and teachers are strictly locked to their registered institute.
27:   // Admins are system administrators who can view, switch, and manage any institute campus.
28:   const userRole = ((session.user as Record<string, unknown>).role as string || "").toUpperCase();
29:   const isAdmin = userRole === "ADMIN";
30: 
31:   let userInstituteCode = "ics";
32:   if (session.user.instituteId) {
33:     const userInstitute = await db.institute.findUnique({
34:       where: { id: session.user.instituteId },
35:       select: { code: true },
36:     });
37:     if (userInstitute?.code) {
38:       userInstituteCode = userInstitute.code.toLowerCase();
39:     }
40:   }
41: 
42:   if (!isAdmin && userInstituteCode !== institute.toLowerCase()) {
43:     redirect(`/${userInstituteCode}`);
44:   }
45: 
46:   const theme = getInstituteTheme(institute);
47: 
48:   // Compute activity eligibility for the sidebar
49:   const activityEligible = await isEligibleForActivities({
50:     user: {
51:       id: session.user.id,
52:       role: session.user.role as string,
53:       instituteId: session.user.instituteId as string,
54:     },
55:   });
56: 
57:   // Compute Knowledge Exchange eligibility for the sidebar
58:   const isKxSessionEligible = await isEligibleForKnowledgeExchange({
59:     user: {
60:       id: session.user.id,
61:       role: session.user.role as string,
62:       instituteId: session.user.instituteId as string,
63:     },
64:   });
65:   const kxEligible = institute.toLowerCase() === "ics" && isKxSessionEligible;
66: 
67:   const role = (session.user.role as string).toUpperCase();
68:   const isStudent = role === "STUDENT";
69:   const isProfessor = role === "PROFESSOR" || role === "TEACHER";
70:   let enrolledCourses: { id: string; title: string; code: string }[] = [];
71: 
72:   const instituteRecord = await db.institute.findUnique({
73:     where: { code: institute.toLowerCase() },
74:     select: { id: true },
75:   });
76: 
77:   if (instituteRecord) {
78:     if (isStudent) {
79:       const enrollments = await db.enrollment.findMany({
80:         where: {
81:           studentId: session.user.id,
82:           status: "APPROVED",
83:           course: {
84:             instituteId: instituteRecord.id,
85:             isArchived: false,
86:           },
87:         },
88:         select: {
89:           course: {
90:             select: {
91:               id: true,
92:               title: true,
93:               code: true,
94:             },
95:           },
96:         },
97:         orderBy: { displayOrderIndex: "asc" },
98:       });
99: 
100:       enrolledCourses = enrollments.map((e) => e.course);
101:     } else if (isProfessor) {
102:       const taught = await db.course.findMany({
103:         where: {
104:           instructorId: session.user.id,
105:           instituteId: instituteRecord.id,
106:           isArchived: false,
107:         },
108:         select: {
109:           id: true,
110:           title: true,
111:           code: true,
112:         },
113:         orderBy: { code: "asc" },
114:       });
115: 
116:       enrolledCourses = taught;
117:     }
118:   }
119: 
120:   // Process daily login reward for student (increments streak & awards EXP on new day)
121:   if (session.user.role === "STUDENT") {
122:     try {
123:       await processLoginReward(session.user.id);
124:     } catch (err) {
125:       console.error("Failed to process login reward on layout load:", err);
126:     }
127:   }
128: 
129:   // Fetch gamification profile for user (level badge in topbar & streak modal)
130:   let gamification = await db.gamificationProfile.findUnique({
131:     where: { studentId: session.user.id },
132:     select: { exp: true, loginStreakCurrent: true },
133:   });
134: 
135:   return (
136:     <DashboardLayout
137:       instituteCode={theme.code}
138:       instituteName={theme.name}
139:       userName={session.user.name as string}
140:       userRole={session.user.role as string}
141:       studentNumber={(session.user.studentNumber as string | undefined) || null}
142:       avatarUrl={(session.user as Record<string, unknown>).avatarUrl as string | null ?? null}
143:       theme={theme}
144:       isEligibleForActivities={activityEligible}
145:       isEligibleForKnowledgeExchange={kxEligible}
146:       enrolledCourses={enrolledCourses}
147:       exp={gamification?.exp || 0}
148:       streakCurrent={gamification?.loginStreakCurrent || 1}
149:       userId={session.user.id}
150:     >
151:       {children}
152:     </DashboardLayout>
153:   );
154: }
155:

1: import { redirect } from "next/navigation";
2: import { getSession } from "@/lib/auth-session";
3: 
4: type PageProps = {
5:   params: Promise<{
6:     institute: string;
7:   }>;
8: };
9: 
10: export default async function InstituteDashboardPage({ params }: PageProps) {
11:   const { institute } = await params;
12:   const session = await getSession();
13: 
14:   if (!session) {
15:     redirect(`/login?institute=${institute}`);
16:   }
17: 
18:   const role = session.user.role.toUpperCase();
19: 
20:   if (role === "STUDENT") {
21:     redirect(`/${institute}/students`);
22:   } else if (role === "PROFESSOR" || role === "TEACHER") {
23:     redirect(`/${institute}/teachers`);
24:   } else if (role === "ADMIN") {
25:     redirect(`/${institute}/admin`);
26:   }
27: 
28:   // Fallback if role is unknown
29:   return <div>Unknown role</div>;
30: }

apps/web/src/components/layout/Dashboard.numberedContent:
1: "use client";
2: 
3: import { Suspense, useState } from "react";
4: import Sidebar from "@/components/layout/Sidebar";
5: import type { EnrolledCourseSummary } from "@/components/layout/Sidebar";
6: import Topbar from "@/components/layout/Topbar";
7: import NavigationProgress from "@/components/layout/NavigationProgress";
8: import Toaster from "@/components/common/Toast";
9: import { AvatarProvider } from "@/lib/avatar-context";
10: import { ThemeProvider } from "@/lib/theme-context";
11: import { ChatbotProvider } from "@/lib/chatbot-context";
12: import ChatbotWidget from "@/components/common/ChatbotWidget";
13: import BadgeToastProvider from "@/components/common/BadgeToast";
14: import LoginRewardModal from "@/components/common/LoginRewardModal";
15: import FloatingStudyTimer from "@/components/common/FloatingStudyTimer";
16: import MobileBottomNav from "@/components/layout/MobileBottomNav";
17: import type { InstituteTheme } from "@/lib/theme";
18: 
19: interface DashboardLayoutProps {
20:   instituteCode: string;
21:   instituteName: string;
22:   userName: string;
23:   userRole: string;
24:   studentNumber?: string | null;
25:   avatarUrl?: string | null;
26:   theme: InstituteTheme;
27:   /** Whether this user qualifies for ICS Interactive Activities. Controls sidebar entry visibility. */
28:   isEligibleForActivities?: boolean;
29:   /** Whether this user qualifies for Knowledge Exchange. Controls sidebar entry visibility. */
30:   isEligibleForKnowledgeExchange?: boolean;
31:   /** Enrolled courses for student sidebar accordion. */
32:   enrolledCourses?: EnrolledCourseSummary[];
33:   /** Gamification total EXP for LevelBadge */
34:   exp?: number;
35:   /** Current login streak */
36:   streakCurrent?: number;
37:   userId?: string;
38:   children: React.ReactNode;
39: }
40: 
41: export default function DashboardLayout({
42:   instituteCode,
43:   instituteName,
44:   userName,
45:   userRole,
46:   studentNumber,
47:   avatarUrl,
48:   theme,
49:   isEligibleForActivities,
50:   isEligibleForKnowledgeExchange,
51:   enrolledCourses,
52:   exp = 0,
53:   streakCurrent = 0,
54:   userId,
55:   children,
56: }: DashboardLayoutProps) {
57:   const [mobileOpen, setMobileOpen] = useState(false);
58:   const [isSidebarCollapsed, setIsSidebarCollapsed] = useState(false);
59: 
60:   const isStudent = userRole.toUpperCase() === "STUDENT";
61: 
62:   const layoutContent = (
63:     <div
64:       className="min-h-[100dvh] bg-canvas text-primary-theme transition-colors duration-200 overflow-x-clip max-w-full"
65:       style={{
66:         "--focus-ring": theme.colors.primary,
67:       } as React.CSSProperties}
68:     >
69:       {/* Navigation Progress Bar */}
70:       <Suspense fallback={null}>
71:         <NavigationProgress color={theme.colors.primary} />
72:       </Suspense>
73: 
74:       <div className="flex">
75:         <Sidebar
76:           instituteCode={instituteCode}
77:           theme={theme}
78:           userRole={userRole}
79:           isCollapsed={isSidebarCollapsed}
80:           onToggleCollapse={() => setIsSidebarCollapsed(!isSidebarCollapsed)}
81:           isEligibleForActivities={isEligibleForActivities}
82:           isEligibleForKnowledgeExchange={isEligibleForKnowledgeExchange}
83:           enrolledCourses={enrolledCourses}
84:         />
85: 
86:         {/* Mobile Sidebar Drawer (Slides in on burger menu click) */}
87:         <div
88:           className={`fixed inset-0 z-[60] lg:hidden transition-all duration-300 ${
89:             mobileOpen ? "pointer-events-auto opacity-100" : "pointer-events-none opacity-0"
90:           }`}
91:           aria-hidden={!mobileOpen}
92:         >
93:           {/* Backdrop scrim */}
94:           <div
95:             className="absolute inset-0 bg-black/60 backdrop-blur-xs transition-opacity duration-300"
96:             onClick={() => setMobileOpen(false)}
97:           />
98:           {/* Drawer container */}
99:           <div
100:             className={`relative z-10 h-full max-w-[280px] w-[80vw] transition-transform duration-300 ease-in-out ${
101:               mobileOpen ? "translate-x-0" : "-translate-x-full"
102:             }`}
103:           >
104:             <Sidebar
105:               instituteCode={instituteCode}
106:               theme={theme}
107:               userRole={userRole}
108:               isCollapsed={false}
109:               isMobileDrawer={true}
110:               onCloseMobileDrawer={() => setMobileOpen(false)}
111:               isEligibleForActivities={isEligibleForActivities}
112:               isEligibleForKnowledgeExchange={isEligibleForKnowledgeExchange}
113:               enrolledCourses={enrolledCourses}
114:             />
115:           </div>
116:         </div>
117: 
118:         <div className={`min-w-0 flex-1 overflow-x-hidden max-w-full transition-all duration-300 ${
119:           isSidebarCollapsed ? "lg:pl-[72px]" : "lg:pl-72"
120:         }`}>
121:           <Topbar
122:             theme={theme}
123:             instituteName={instituteName}
124:             userName={userName}
125:             userRole={userRole}
126:             studentNumber={studentNumber}
127:             avatarUrl={avatarUrl ?? null}
128:             instituteCode={instituteCode}
129:             exp={exp}
130:             onOpenMobileMenu={() => setMobileOpen(true)}
131:           />
132:           <main className="px-4 py-4 lg:px-8 lg:py-8 pb-[calc(120px+env(safe-area-inset-bottom,0px))] lg:pb-8">
133:             <AvatarProvider initialAvatarUrl={avatarUrl ?? null}>
134:               {children}
135:             </AvatarProvider>
136:           </main>
137:         </div>
138:       </div>
139: 
140:       {/* Toast Notifications */}
141:       <Toaster />
142: 
143:       {/* Mobile Bottom Navigation */}
144:       <MobileBottomNav
145:         instituteCode={instituteCode}
146:         primaryColor={theme.colors.primary}
147:         userRole={userRole}
148:         userName={userName}
149:         avatarUrl={avatarUrl ?? null}
150:       />
151: 
152:       {/* Gamification Badge Toasts */}
153:       <BadgeToastProvider />
154: 
155:       {/* Student Gamification Widgets */}
156:       {isStudent && (
157:         <>
158:           <LoginRewardModal
159:             userId={userId}
160:             streakCurrent={streakCurrent}
161:             expEarned={10}
162:             totalExp={exp}
163:           />
164:           <FloatingStudyTimer />
165:           <ChatbotWidget theme={theme} />
166:         </>
167:       )}
168:     </div>
169:   );
170: 
171:   return (
172:     <ThemeProvider>
173:       {isStudent ? (
174:         <ChatbotProvider>{layoutContent}</ChatbotProvider>
175:       ) : (
176:         layoutContent
177:       )}
178:     </ThemeProvider>
179:   );
180: }

