46:   ];
47: 
48:   const adminTabs = [
49:     { name: "Dashboard", href: `/${instituteCode}/admin`, icon: LayoutDashboard },
50:     { name: "Courses", href: `/${instituteCode}/admin/courses`, icon: BookOpen },
51:     { name: "Accounts", href: `/${instituteCode}/accounts`, icon: Trophy },
52:     { name: "Logs", href: `/${instituteCode}/logs`, icon: Megaphone },
53:     { name: "More", isMore: true, icon: MoreHorizontal },
54:   ];
55: 
56:   const tabs = isStudent ? studentTabs : isProfessor ? teacherTabs : adminTabs;
57: 
58:   const lastToggleRef = useRef<number>(0);
59: 
60:   const handleMoreToggle = () => {
61:     const now = Date.now();
62:     if (now - lastToggleRef.current < 350) return;
63:     lastToggleRef.current = now;
64:     try {
65:       triggerNativeHaptic("light");
66:     } catch {}
67:     setIsMoreOpen((prev) => !prev);
68:   };
69: 
70:   return (
71:     <>
72:       <nav className="fixed bottom-0 left-0 right-0 z-[90] lg:hidden bg-white dark:bg-[#1A1D27] border-t border-slate-200/80 dark:border-white/10 pb-[env(safe-area-inset-bottom)] shadow-lg">
73:         <div className="flex justify-around items-center min-h-[56px] px-1">
74:           {tabs.map((tab) => {
75:             const Icon = tab.icon;
76: 
77:             if (tab.isMore) {
78:               const isActive = isMoreOpen;
79:               return (
80:                 <button
81:                   key={tab.name}
82:                   id="mobile-nav-more"
83:                   type="button"
84:                   onClick={handleMoreToggle}
85:                   className="flex flex-col items-center justify-center flex-1 min-w-0 max-w-[80px] min-h-[44px] gap-1 py-1.5 px-0.5 active:scale-95 transition-transform cursor-pointer touch-manipulation select-none"
86:                   style={{ color: isActive ? primaryColor : undefined }}
87:                   aria-label="Open more navigation options"
88:                   aria-expanded={isMoreOpen}
89:                 >
90:                   <Icon
91:                     className={`w-5 h-5 shrink-0 ${isActive ? "" : "text-slate-500 dark:text-slate-400"}`}
92:                   />
93:                   <span
94:                     className={`text-[10px] font-medium leading-tight truncate w-full text-center tracking-tight ${isActive ? "font-bold" : "text-slate-500 dark:text-slate-400"}`}
95:                   >
96:                     {tab.name}
97:                   </span>
98:                 </button>
99:               );
100:             }
101: 
102:             const href = tab.href!;
103:             const isActive =
104:               href.endsWith("/courses")
105:                 ? pathname === href || pathname.startsWith(href + "/")
106:                 : pathname === href;
107: 
108:             return (
109:               <Link
110:                 key={tab.name}
111:                 href={href}
112:                 className="flex flex-col items-center justify-center flex-1 min-w-0 max-w-[80px] min-h-[44px] gap-1 py-1.5 px-0.5 active:scale-95 transition-transform cursor-pointer touch-manipulation select-none"
113:                 style={{ color: isActive ? primaryColor : undefined }}
114:               >
115:                 <Icon
116:                   className={`w-5 h-5 shrink-0 ${isActive ? "" : "text-slate-500 dark:text-slate-400"}`}
117:                 />
118:                 <span
119:                   className={`text-[10px] font-medium leading-tight truncate w-full text-center tracking-tight ${isActive ? "font-bold" : "text-slate-500 dark:text-slate-400"}`}
120:                 >
121:                   {tab.name}
122:                 </span>
123:               </Link>
124:             );
125:           })}
126:         </div>
127:       </nav>
128: 
129:       {/* More Options Bottom Sheet */}
130:       <MobileMoreSheet
131: 
132:         isOpen={isMoreOpen}
133:         onClose={() => setIsMoreOpen(false)}
134:         instituteCode={instituteCode}
135:         primaryColor={primaryColor}
136:         userRole={userRole}
137:         userName={userName}
138:         avatarUrl={avatarUrl}
139:       />
140:     </>
141:   );
142: }
