apps/web/src/components/layout/MobileMor.numberedContent:
1: "use client";
2: import { useEffect, useRef, useState } from "react";
3: import Link from "next/link";
4: import { usePathname, useRouter } from "next/navigation";
5: import {
6:   X,
7:   BookOpen,
8:   CheckSquare,
9:   Trophy,
10:   Award,
11:   BarChart2,
12:   Archive,
13:   PlusSquare,
14:   ShieldCheck,
15:   Users,
16:   FileText,
17:   Library,
18:   Flame,
19:   User,
20:   Settings,
21:   LogOut,
22:   Sparkles,
23:   type LucideIcon,
24: } from "lucide-react";
25: import UserAvatar from "@/components/common/UserAvatar";
26: import { triggerNativeHaptic, logoutFromNative } from "@/lib/mobile-bridge";
27: 
28: interface MobileMoreSheetProps {
29:   isOpen: boolean;
30:   onClose: () => void;
31:   instituteCode: string;
32:   primaryColor: string;
33:   userRole: string;
34:   userName?: string;
35:   avatarUrl?: string | null;
36: }
37: 
38: interface NavItem {
39:   label: string;
40:   href: string;
41:   icon: LucideIcon;
42:   description?: string;
43: }
44: 
45: export default function MobileMoreSheet({
46:   isOpen,
47:   onClose,
48:   instituteCode,
49:   primaryColor,
50:   userRole,
51:   userName = "User",
52:   avatarUrl = null,
53: }: MobileMoreSheetProps) {
54:   const pathname = usePathname();
55:   const router = useRouter();
56:   const sheetRef = useRef<HTMLDivElement>(null);
57:   const [loggingOut, setLoggingOut] = useState(false);
58:   const role = userRole.toUpperCase();
59:   const isStudent = role === "STUDENT";
60:   const isProfessor = role === "PROFESSOR" || role === "TEACHER";
61: 
62:   // Lock body scroll when sheet is open
63:   useEffect(() => {
64:     if (isOpen) {
65:       document.body.style.overflow = "hidden";
66:     } else {
67:       document.body.style.overflow = "";
68:     }
69:     return () => {
70:       document.body.style.overflow = "";
71:     };
72:   }, [isOpen]);
73: 
74:   // Handle escape key
75:   useEffect(() => {
76:     function handleKeyDown(e: KeyboardEvent) {
77:       if (e.key === "Escape" && isOpen) {
78:         onClose();
79:       }
80:     }
81:     window.addEventListener("keydown", handleKeyDown);
82:     return () => window.removeEventListener("keydown", handleKeyDown);
83:   }, [isOpen, onClose]);
84: 
85:   const studentItems: NavItem[] = [
86:     { label: "Flashcards", href: `/${instituteCode}/flashcards`, icon: Flame, description: "Daily review decks" },
87:     { label: "Materials", href: `/${instituteCode}/learning-materials`, icon: BookOpen, description: "Academic library" },
88:     { label: "Tasks", href: `/${instituteCode}/tasks`, icon: CheckSquare, description: "Personal planner" },
89:     { label: "Leaderboards", href: `/${instituteCode}/leaderboards`, icon: Trophy, description: "Institute standings" },
90:     { label: "Achievements", href: `/${instituteCode}/achievements`, icon: Award, description: "Badges and EXP" },
91:   ];
92: 
93:   const teacherItems: NavItem[] = [
94:     { label: "Analytics", href: `/${instituteCode}/analytics`, icon: BarChart2, description: "Student telemetry" },
95:     { label: "Leaderboard", href: `/${instituteCode}/manage-leaderboard`, icon: Trophy, description: "Manage rankings" },
96:     { label: "Create Tasks", href: `/${instituteCode}/create-tasks`, icon: PlusSquare, description: "Assign activities" },
97:     { label: "Archived", href: `/${instituteCode}/courses/archived`, icon: Archive, description: "Previous courses" },
98:   ];
99: 
100:   const adminItems: NavItem[] = [
101:     { label: "Courses", href: `/${instituteCode}/admin/courses`, icon: Library, description: "All classes" },
102:     { label: "Accounts", href: `/${instituteCode}/accounts`, icon: Users, description: "Users & students" },
103:     { label: "Permissions", href: `/${instituteCode}/accounts/permissions`, icon: ShieldCheck, description: "Role matrix" },
104:     { label: "Audit Logs", href: `/${instituteCode}/logs`, icon: FileText, description: "System events" },
105:   ];
106: 
107:   const handleLogout = async () => {
108:     triggerNativeHaptic("medium");
109:     setLoggingOut(true);
110:     try {
111:       logoutFromNative();
112:       await fetch("/api/auth/logout", { method: "POST" });
113:     } catch {
114:       // ignore
115:     }
116:     onClose();
117:     router.push(`/login?institute=${instituteCode}&force=true`);
118:   };
119: 
120:   const items = isStudent ? studentItems : isProfessor ? teacherItems : adminItems;
121: 
122:   if (!isOpen) return null;
123: 
124:   return (
125:     <div className="fixed inset-0 z-[100] lg:hidden">
126:       {/* Backdrop scrim */}
127:       <div
128:         className="fixed inset-0 bg-black/60 backdrop-blur-sm transition-opacity duration-300 touch-manipulation"
129:         onClick={onClose}
130:         onTouchEnd={(e) => {
131:           if (e.target === e.currentTarget) {
132:             e.preventDefault();
133:             onClose();
134:           }
135:         }}
136:         aria-hidden="true"
137:       />
138: 
139:       {/* Bottom Sheet Container */}
140:       <div
141:         ref={sheetRef}
142:         role="dialog"
143:         aria-modal="true"
144:         aria-label="More navigation options"
145:         className="fixed inset-x-0 bottom-0 z-10 max-h-[85vh] flex flex-col rounded-t-[28px] border-t border-slate-200/80 dark:border-white/10 bg-white dark:bg-[#141721] shadow-2xl overflow-hidden transition-transform duration-300 ease-out"
146:       >
147:         {/* Handle bar + Header */}
148:         <div className="px-5 pt-3 pb-3 border-b border-slate-100 dark:border-white/5 flex items-center justify-between shrink-0">
149:           <div className="flex items-center gap-2.5">
150:             <div className="w-8 h-1 rounded-full bg-slate-300 dark:bg-white/20 mx-auto absolute top-2.5 left-1/2 -translate-x-1/2" />
151:             <h2 className="text-base font-bold text-slate-900 dark:text-[#F0F2F8] mt-1">
152:               Explore CdM LMS
153:             </h2>
154:             <span
155:               className="mt-1 px-2 py-0.5 rounded-md text-[10px] font-black uppercase tracking-wider text-white shrink-0"
156:               style={{ backgroundColor: primaryColor }}
157:             >
158:               {instituteCode.toUpperCase()}
159:             </span>
160:           </div>
161:           <button
162:             type="button"
163:             onClick={onClose}
164:             className="rounded-xl p-2 text-slate-400 hover:text-slate-700 dark:hover:text-[#F0F2F8] hover:bg-slate-100 dark:hover:bg-white/5 transition-colors cursor-pointer min-h-[44px] min-w-[44px] flex items-center justify-center touch-manipulation"
165:             aria-label="Close menu"
166:           >
167:             <X className="w-5 h-5" />
168:           </button>
169:         </div>
170: 
171:         {/* User Card */}
172:         <div className="px-4 pt-3 pb-2 shrink-0">
173:           <div className="p-3 rounded-2xl border border-slate-200/70 dark:border-white/10 bg-slate-50/70 dark:bg-white/[0.03] flex items-center justify-between gap-3">
174:             <div className="flex items-center gap-3 min-w-0 flex-1">
175:               <UserAvatar
176:                 name={userName}
177:                 avatarUrl={avatarUrl}
178:                 size="sm"
179:                 color={primaryColor}
180:                 className="h-10 w-10 shrink-0 text-xs"
181:               />
182:               <div className="min-w-0 flex-1">
183:                 <p className="text-xs font-bold text-slate-900 dark:text-[#F0F2F8] truncate">
184:                   {userName}
185:                 </p>
186:                 <p className="text-[10px] font-semibold uppercase tracking-wider text-slate-400 dark:text-[#8B92A5] truncate">
187:                   {userRole}
188:                 </p>
189:               </div>
190:             </div>
191: 
192:             <div className="flex items-center gap-1.5 shrink-0">
193:               <Link
194:                 href={`/${instituteCode}/profile`}
195:                 onClick={() => {
196:                   triggerNativeHaptic("light");
197:                   onClose();
198:                 }}
199:                 className="rounded-xl text-slate-600 dark:text-slate-300 hover:bg-slate-200/60 dark:hover:bg-white/10 transition-colors min-h-[44px] min-w-[44px] flex items-center justify-center active:scale-95"
200:                 title="Profile"
201:                 aria-label="Profile"
202:               >
203:                 <User className="w-4 h-4" />
204:               </Link>
205:               <Link
206:                 href={`/${instituteCode}/settings`}
207:                 onClick={() => {
208:                   triggerNativeHaptic("light");
209:                   onClose();
210:                 }}
211:                 className="rounded-xl text-slate-600 dark:text-slate-300 hover:bg-slate-200/60 dark:hover:bg-white/10 transition-colors min-h-[44px] min-w-[44px] flex items-center justify-center active:scale-95"
212:                 title="Settings"
213:                 aria-label="Settings"
214:               >
215:                 <Settings className="w-4 h-4" />
216:               </Link>
217:             </div>
218:           </div>
219:         </div>
220: 
221:         {/* Scrollable Navigation Grid */}
222:         <div className="flex-1 overflow-y-auto px-4 py-2">
223:           <div className="grid grid-cols-2 gap-2.5">
224:             {items.map((item) => {
225:               const Icon = item.icon;
226:               const isActive = pathname === item.href || pathname.startsWith(item.href + "/");
227: 
228:               return (
229:                 <Link
230:                   key={item.label}
231:                   href={item.href}
232:                   onClick={() => {
233:                     triggerNativeHaptic("light");
234:                     onClose();
235:                   }}
236:                   className={`flex flex-col p-3 rounded-2xl border transition-all cursor-pointer min-h-[72px] active:scale-[0.98] touch-manipulation ${
237:                     isActive
238:                       ? "border-transparent bg-slate-100/90 dark:bg-white/10"
239:                       : "border-slate-200/70 dark:border-white/5 bg-slate-50/50 dark:bg-[#1A1D27] hover:bg-slate-100/70 dark:hover:bg-white/[0.07]"
240:                   }`}
241:                   style={
242:                     isActive
243:                       ? {
244:                           borderColor: primaryColor,
245:                           color: primaryColor,
246:                         }
247:                       : undefined
248:                   }
249:                 >
250:                   <div className="flex items-center gap-2.5 mb-1 min-w-0">
251:                     <div
252:                       className="p-1.5 rounded-xl shrink-0"
253:                       style={{
254:                         backgroundColor: isActive ? `${primaryColor}25` : undefined,
255:                       }}
256:                     >
257:                       <Icon
258:                         className="w-4 h-4"
259:                         style={{ color: isActive ? primaryColor : undefined }}
260:                       />
261:                     </div>
262:                     <span className="text-xs font-bold text-slate-900 dark:text-[#F0F2F8] truncate flex-1 min-w-0">
263:                       {item.label}
264:                     </span>
265:                   </div>
266:                   {item.description && (
267:                     <span className="text-[10px] text-slate-500 dark:text-[#8B92A5] truncate">
268:                       {item.description}
269:                     </span>
270:                   )}
271:                 </Link>
272:               );
273:             })}
274:           </div>
275:         </div>
276: 
277:         {/* Bottom Sign Out / Switch Account */}
278:         <div className="p-4 pt-2 pb-[calc(24px+env(safe-area-inset-bottom,0px))] border-t border-slate-100 dark:border-white/5 shrink-0">
279:           <button
280:             type="button"
281:             disabled={loggingOut}
282:             onClick={handleLogout}
283:             className="w-full flex items-center justify-center gap-2.5 py-3 px-4 rounded-2xl bg-rose-500/10 hover:bg-rose-500/20 text-rose-600 dark:text-rose-400 font-bold text-xs border border-rose-500/20 transition-all cursor-pointer active:scale-[0.98] min-h-[48px] touch-manipulation"
284:           >
285:             <LogOut className="w-4 h-4" />
286:             <span>{loggingOut ? "Signing Out..." : "Sign Out / Switch Account"}</span>
287:           </button>
288:         </div>
289:       </div>
290:     </div>
291:   );
292: }
