apps/web/src/components/layout/Sidebar.t.numberedContent:
1: "use client";
2: 
3: import { useState } from "react";
4: import Link from "next/link";
5: import { usePathname } from "next/navigation";
6: import {
7:   LayoutDashboard,
8:   BookOpen,
9:   ClipboardCheck,
10:   Megaphone,
11:   ListTodo,
12:   Trophy,
13:   PanelLeftClose,
14:   PanelLeftOpen,
15:   GraduationCap,
16:   BarChart2,
17:   PlusSquare,
18:   Users,
19:   FileText,
20:   HardDrive,
21:   ShieldCheck,
22:   Library,
23:   Archive,
24:   FlaskConical,
25:   Code2,
26:   Terminal,
27:   ChevronDown,
28:   ChevronRight,
29:   PenTool,
30:   Settings,
31:   HelpCircle,
32:   MessageSquareQuote,
33:   X,
34:   type LucideIcon,
35: } from "lucide-react";
36: import FlashcardIcon from "@/components/icons/FlashcardIcon";
37: import type { InstituteTheme } from "@/lib/theme";
38: 
39: 
40: import type { ComponentType } from "react";
41: 
42: interface NavLink {
43:   label: string;
44:   href: string;
45:   icon: ComponentType<{ className?: string }>;
46: }
47: 
48: export interface EnrolledCourseSummary {
49:   id: string;
50:   title: string;
51:   code: string;
52: }
53: 
54: interface SidebarProps {
55:   instituteCode: string;
56:   theme: InstituteTheme;
57:   userRole: string;
58:   isCollapsed?: boolean;
59:   onToggleCollapse?: () => void;
60:   isMobileDrawer?: boolean;
61:   onCloseMobileDrawer?: () => void;
62:   /** When true, renders the "Interactive Labs" nav entry. Must be completely absent from DOM when false. */
63:   isEligibleForActivities?: boolean;
64:   /** When true, renders the "Knowledge Exchange" nav entry. Must be completely absent from DOM when false. */
65:   isEligibleForKnowledgeExchange?: boolean;
66:   /** Enrolled courses for the student to render under the "My Courses" accordion. */
67:   enrolledCourses?: EnrolledCourseSummary[];
68: }
69: 
70: /** Sidebar link ID for "My Courses" — used to detect the accordion item. */
71: const MY_COURSES_KEY = "my-courses";
72: 
73: const getStudentLinks = (code: string): (NavLink & { key?: string })[] => [
74:   { label: "Dashboard", href: `/${code}/students`, icon: LayoutDashboard },
75:   { label: "My Courses", href: `/${code}/courses`, icon: BookOpen, key: MY_COURSES_KEY },
76:   { label: "Learning Materials", href: `/${code}/learning-materials`, icon: BookOpen },
77:   { label: "Announcements", href: `/${code}/announcements`, icon: Megaphone },
78:   { label: "Grades", href: `/${code}/grades`, icon: GraduationCap },
79:   { label: "Tasks", href: `/${code}/tasks`, icon: ListTodo },
80:   { label: "Flashcards", href: `/${code}/flashcards`, icon: FlashcardIcon },
81:   { label: "Leaderboards", href: `/${code}/leaderboards`, icon: Trophy },
82: ];
83: 
84: const getProfessorLinks = (code: string): (NavLink & { key?: string })[] => [
85:   { label: "Dashboard", href: `/${code}/teachers`, icon: LayoutDashboard },
86:   { label: "My Classes", href: `/${code}/courses`, icon: BookOpen, key: MY_COURSES_KEY },
87:   { label: "Archived Classes", href: `/${code}/courses/archived`, icon: Archive },
88: 
89:   { label: "Student Analytics", href: `/${code}/analytics`, icon: BarChart2 },
90:   { label: "Manage Leaderboard", href: `/${code}/manage-leaderboard`, icon: Trophy },
91: ];
92: 
93: const getAdminLinks = (code: string): NavLink[] => [
94:   { label: "Dashboard", href: `/${code}/admin`, icon: LayoutDashboard },
95:   { label: "Course Management", href: `/${code}/admin/courses`, icon: Library },
96:   { label: "Account Management", href: `/${code}/accounts`, icon: Users },
97:   { label: "Permissions", href: `/${code}/accounts/permissions`, icon: ShieldCheck },
98:   { label: "Audit Logs", href: `/${code}/logs`, icon: FileText },
99:   { label: "Backup & Recovery", href: `/${code}/backup`, icon: HardDrive },
100:   { label: "Security Tools", href: `/${code}/security`, icon: ShieldCheck },
101:   { label: "Settings", href: `/${code}/settings`, icon: Settings },
102:   { label: "Help", href: `/${code}/help`, icon: HelpCircle },
103: ];
104: 
105: function getLinks(instituteCode: string, role: string): (NavLink & { key?: string })[] {
106:   const r = role.toUpperCase();
107:   if (r === "PROFESSOR" || r === "TEACHER") return getProfessorLinks(instituteCode);
108:   if (r === "ADMIN") return getAdminLinks(instituteCode);
109:   return getStudentLinks(instituteCode);
110: }
111: 
112: export default function Sidebar({
113:   instituteCode,
114:   theme,
115:   userRole,
116:   isCollapsed,
117:   onToggleCollapse,
118:   isMobileDrawer = false,
119:   onCloseMobileDrawer,
120:   isEligibleForActivities,
121:   isEligibleForKnowledgeExchange,
122:   enrolledCourses,
123: }: SidebarProps) {
124:   const pathname = usePathname();
125:   const [isMyCoursesOpen, setIsMyCoursesOpen] = useState(false);
126: 
127:   const isStudent = userRole.toUpperCase() === "STUDENT";
128:   const isProfessor = userRole.toUpperCase() === "PROFESSOR" || userRole.toUpperCase() === "TEACHER";
129: 
130:   // Build link list identically on both server and client (avoids hydration mismatch)
131:   let links = getLinks(instituteCode, userRole);
132: 
133:   if (isEligibleForActivities) {
134:     if (isProfessor) {
135:       links = [
136:         ...links,
137:         { label: "CodeLab", href: `/${instituteCode}/activities/codelab`, icon: Code2 },
138:         { label: "CodeLab Analytics", href: `/${instituteCode}/activities/codelab/instructor`, icon: Terminal },
139:       ];
140:     } else if (isStudent) {
141:       links = [
142:         ...links,
143:         { label: "CodeLab", href: `/${instituteCode}/activities/codelab`, icon: Code2 },
144:       ];
145:     }
146:   }
147: 
148:   if (isEligibleForKnowledgeExchange) {
149:     links = [
150:       ...links,
151:       {
152:         label: "Knowledge Exchange",
153:         href: `/${instituteCode}/knowledge-exchange`,
154:         icon: MessageSquareQuote,
155:       },
156:     ];
157:   }
158: 
159: 
160:   // Find the active link by getting the longest href that matches the current pathname
161:   const activeLink = [...links]
162:     .sort((a, b) => b.href.length - a.href.length)
163:     .find(
164:       (link) => pathname === link.href || pathname.startsWith(link.href + "/")
165:     );
166: 
167:   const handleMyCoursesToggle = () => {
168:     setIsMyCoursesOpen((prev) => !prev);
169:   };
170: 
171:   const handleMyCoursesKeyDown = (e: React.KeyboardEvent) => {
172:     if (e.key === "Enter" || e.key === " ") {
173:       e.preventDefault();
174:       handleMyCoursesToggle();
175:     }
176:   };
177: 
178:   const handleLinkClick = () => {
179:     if (isMobileDrawer && onCloseMobileDrawer) {
180:       onCloseMobileDrawer();
181:     }
182:   };
183: 
184:   return (
185:     <aside
186:       className={`${
187:         isMobileDrawer
188:           ? "flex h-full w-full shrink-0 border-r flex-col overflow-y-auto bg-white dark:bg-[#12151E] border-slate-200/80 dark:border-white/5 shadow-2xl"
189:           : `hidden h-screen border-r flex-col lg:fixed lg:top-0 lg:bottom-0 lg:left-0 lg:z-30 lg:flex transition-all duration-300 ease-in-out overflow-hidden bg-white dark:bg-[#12151E] border-slate-200/80 dark:border-white/5 shadow-xs ${
190:               isCollapsed ? "w-[72px]" : "w-72"
191:             }`
192:       }`}
193:     >
194:       {/* Header with logo + collapse toggle */}
195:       <div className="flex items-center h-16 shrink-0 border-b border-slate-200/80 dark:border-white/5 bg-transparent px-4 gap-2">
196:         <div
197:           className={`flex items-center gap-2 overflow-hidden transition-all duration-300 flex-1 min-w-0 ${
198:             !isMobileDrawer && isCollapsed ? "opacity-0 w-0 pointer-events-none" : "opacity-100"
199:           }`}
200:         >
201:           <Link
202:             href={`/${instituteCode}`}
203:             onClick={handleLinkClick}
204:             className="flex items-center gap-2 group"
205:           >
206:             <span
207:               className="text-lg font-bold text-slate-900 dark:text-[#F0F2F8] tracking-tight whitespace-nowrap transition-colors"
208:             >
209:               CdM LMS
210:             </span>
211:             <span
212:               className="h-2 w-2 rounded-full shrink-0 animate-pulse"
213:               style={{ backgroundColor: theme.colors.primary }}
214:             />
215:           </Link>
216:         </div>
217: 
218:         {isMobileDrawer ? (
219:           <button
220:             type="button"
221:             onClick={onCloseMobileDrawer}
222:             className="shrink-0 flex items-center justify-center h-8 w-8 rounded-xl text-slate-500 hover:text-slate-900 hover:bg-slate-100 dark:text-[#8B92A5] dark:hover:bg-white/[0.05] dark:hover:text-[#F0F2F8] transition-colors cursor-pointer"
223:             aria-label="Close sidebar"
224:           >
225:             <X className="h-5 w-5" />
226:           </button>
227:         ) : onToggleCollapse ? (
228:           <button
229:             type="button"
230:             onClick={onToggleCollapse}
231:             className="shrink-0 flex items-center justify-center h-8 w-8 rounded-xl text-slate-500 hover:text-slate-900 hover:bg-slate-100 dark:text-[#8B92A5] dark:hover:bg-white/[0.05] dark:hover:text-[#F0F2F8] transition-colors cursor-pointer"
232:             aria-label={isCollapsed ? "Expand sidebar" : "Collapse sidebar"}
233:           >
234:             {isCollapsed ? (
235:               <PanelLeftOpen className="h-5 w-5" />
236:             ) : (
237:               <PanelLeftClose className="h-5 w-5" />
238:             )}
239:           </button>
240:         ) : null}
241:       </div>
242: 
243:       {/* Scrollable Nav */}
244:       <nav className="flex-1 overflow-y-auto p-3 flex flex-col gap-1">
245:         {links.map((item) => {
246:           const Icon = item.icon;
247:           const active = activeLink?.href === item.href;
248:           const itemKey = "key" in item ? item.key : undefined;
249: 
250:           // Render "My Courses" as an accordion for students and professors
251:           if ((isStudent || isProfessor) && itemKey === MY_COURSES_KEY) {
252:             const isSubActive =
253:               (pathname === `/${instituteCode}/courses` ||
254:                 pathname.startsWith(`/${instituteCode}/courses/`)) &&
255:               !pathname.startsWith(`/${instituteCode}/courses/archived`);
256: 
257:             return (
258:               <div key={item.href} id="sidebar-my-courses-accordion">
259:                 {/* Accordion header */}
260:                 <div
261:                   role="button"
262:                   tabIndex={0}
263:                   id="sidebar-my-courses-toggle"
264:                   aria-expanded={isMyCoursesOpen}
265:                   onClick={handleMyCoursesToggle}
266:                   onKeyDown={handleMyCoursesKeyDown}
267:                   className={`group flex items-center gap-2 px-3 py-2.5 text-sm font-medium transition-all cursor-pointer select-none ${
268:                     isSubActive && !isMyCoursesOpen
269:                       ? "border-l-[3px] font-semibold rounded-r-xl rounded-l-none"
270:                       : "border-l-[3px] border-transparent text-slate-600 hover:text-slate-900 hover:bg-slate-100/80 dark:text-[#8B92A5] dark:hover:bg-white/[0.05] dark:hover:text-[#F0F2F8] rounded-xl"
271:                   }`}
272:                   style={
273:                     isSubActive && !isMyCoursesOpen
274:                       ? {
275:                           borderColor: theme.colors.primary,
276:                           backgroundColor: `${theme.colors.primary}1A`,
277:                           color: theme.colors.primary,
278:                         }
279:                       : undefined
280:                   }
281:                 >
282:                   <Icon className="h-5 w-5 shrink-0 group-hover:scale-105 transition-transform duration-150" />
283:                   <span
284:                     className={`overflow-hidden whitespace-nowrap transition-all duration-300 flex-1 min-w-0 ${
285:                       isCollapsed ? "w-0 opacity-0" : "opacity-100"
286:                     }`}
287:                   >
288:                     {item.label}
289:                   </span>
290:                   {!isCollapsed && (
291:                     <span className="shrink-0">
292:                       <ChevronDown
293:                         className={`h-4 w-4 transition-transform duration-200 text-slate-400 dark:text-[#555C72] ${
294:                           isMyCoursesOpen ? "rotate-0" : "-rotate-90"
295:                         }`}
296:                       />
297:                     </span>
298:                   )}
299:                 </div>
300: 
301:                 {/* Accordion content */}
302:                 {!isCollapsed && (
303:                   <div
304:                     className="overflow-hidden transition-all duration-300 ease-in-out"
305:                     style={{
306:                       maxHeight: isMyCoursesOpen ? `${((enrolledCourses?.length ?? 0) + 2) * 44}px` : "0px",
307:                       opacity: isMyCoursesOpen ? 1 : 0,
308:                     }}
309:                   >
310:                     <div className="flex flex-col gap-0.5 mt-1">
311:                       {/* To-do sub-link (Students only) */}
312:                       {isStudent && (
313:                         <Link
314:                           id="sidebar-my-courses-todo"
315:                           href={`/${instituteCode}/assignments`}
316:                           onClick={handleLinkClick}
317:                           className={`flex items-center gap-2 rounded-xl pl-8 pr-3 py-2 text-xs font-medium transition-colors ${
318:                             pathname === `/${instituteCode}/assignments` ||
319:                             pathname.startsWith(`/${instituteCode}/assignments/`)
320:                               ? "font-semibold"
321:                               : "text-slate-600 hover:text-slate-900 hover:bg-slate-100/80 dark:text-[#8B92A5] dark:hover:bg-white/[0.05] dark:hover:text-[#F0F2F8]"
322:                           }`}
323:                           style={
324:                             pathname === `/${instituteCode}/assignments` ||
325:                             pathname.startsWith(`/${instituteCode}/assignments/`)
326:                               ? {
327:                                   backgroundColor: `${theme.colors.primary}1A`,
328:                                   color: theme.colors.primary,
329:                                 }
330:                               : undefined
331:                           }
332:                         >
333:                           <ClipboardCheck className="h-4 w-4 shrink-0" />
334:                           <span className="truncate">To-do</span>
335:                         </Link>
336:                       )}
337: 
338:                       {/* Enrolled course sub-links */}
339:                       {enrolledCourses?.map((course) => {
340:                         const courseHref = `/${instituteCode}/courses/${course.id}`;
341:                         const isCourseActive =
342:                           pathname === courseHref || pathname.startsWith(courseHref + "/");
343: 
344:                         return (
345:                           <Link
346:                             key={course.id}
347:                             id={`sidebar-course-${course.id}`}
348:                             href={courseHref}
349:                             onClick={handleLinkClick}
350:                             className={`flex items-center gap-2 rounded-xl pl-8 pr-3 py-2 text-xs font-medium transition-colors ${
351:                               isCourseActive
352:                                 ? "font-semibold"
353:                                 : "text-slate-600 hover:text-slate-900 hover:bg-slate-100/80 dark:text-[#8B92A5] dark:hover:bg-white/[0.05] dark:hover:text-[#F0F2F8]"
354:                             }`}
355:                             style={
356:                               isCourseActive
357:                                 ? {
358:                                     backgroundColor: `${theme.colors.primary}1A`,
359:                                     color: theme.colors.primary,
360:                                   }
361:                                 : undefined
362:                             }
363:                           >
364:                             <BookOpen className="h-4 w-4 shrink-0" />
365:                             <span className="truncate">{course.code}</span>
366:                           </Link>
367:                         );
368:                       })}
369:                     </div>
370:                   </div>
371:                 )}
372:               </div>
373:             );
374:           }
375: 
376:           // Regular flat nav link
377:           return (
378:             <Link
379:               key={item.href}
380:               href={item.href}
381:               onClick={handleLinkClick}
382:               title={isCollapsed ? item.label : undefined}
383:               className={`group flex items-center gap-2 px-3 py-2.5 text-sm font-medium transition-all ${
384:                 active
385:                   ? "border-l-[3px] font-semibold rounded-r-xl rounded-l-none"
386:                   : "border-l-[3px] border-transparent text-slate-600 hover:text-slate-900 hover:bg-slate-100/80 dark:text-[#8B92A5] dark:hover:bg-white/[0.05] dark:hover:text-[#F0F2F8] rounded-xl"
387:               }`}
388:               style={
389:                 active
390:                   ? {
391:                       borderColor: theme.colors.primary,
392:                       backgroundColor: `${theme.colors.primary}1A`,
393:                       color: theme.colors.primary,
394:                     }
395:                   : undefined
396:               }
397:             >
398:               <Icon className="h-5 w-5 shrink-0 group-hover:scale-105 transition-transform duration-150" />
399:               <span
400:                 className={`overflow-hidden whitespace-nowrap transition-all duration-300 ${
401:                   isCollapsed ? "w-0 opacity-0" : "opacity-100"
402:                 }`}
403:               >
404:                 {item.label}
405:               </span>
406:             </Link>
407:           );
408:         })}
409:       </nav>
410:     </aside>
411:   );
412: }

apps/web/src/components/layout/Topbar.ts.numberedContent:
1: "use client";
2: 
3: import { useState, useRef, useEffect } from "react";
4: import Link from "next/link";
5: import { usePathname, useRouter } from "next/navigation";
6: import { Bell, Menu, Search, Settings, User, Shield, HelpCircle, LogOut, Sun, Moon, ChevronDown, Check, Building2 } from "lucide-react";
7: import type { InstituteTheme } from "@/lib/theme";
8: import UserAvatar from "@/components/common/UserAvatar";
9: import NotificationBell from "@/components/layout/NotificationBell";
10: import LevelBadge from "@/components/common/LevelBadge";
11: import SearchModal from "@/components/layout/SearchModal";
12: import { useTheme } from "@/lib/theme-context";
13: import { triggerNativeHaptic, logoutFromNative } from "@/lib/mobile-bridge";
14: 
15: const ALL_INSTITUTES = [
16:   { code: "ics", name: "Institute of Computer Studies", short: "ICS", color: "#E06A26" },
17:   { code: "ibe", name: "Institute of Business and Education", short: "IBE", color: "#EAB308" },
18:   { code: "ite", name: "Institute of Technology and Engineering", short: "ITE", color: "#0284C7" },
19: ];
20: 
21: type TopbarProps = {
22:   theme: InstituteTheme;
23:   instituteName: string;
24:   userName: string;
25:   userRole: string;
26:   instituteCode: string;
27:   studentNumber?: string | null;
28:   avatarUrl?: string | null;
29:   exp?: number;
30:   onOpenMobileMenu?: () => void;
31: };
32: 
33: export default function Topbar({
34:   theme,
35:   instituteName,
36:   userName,
37:   userRole,
38:   instituteCode,
39:   studentNumber,
40:   avatarUrl,
41:   exp = 0,
42:   onOpenMobileMenu,
43: }: TopbarProps) {
44:   const pathname = usePathname();
45:   const router = useRouter();
46:   const [isDropdownOpen, setIsDropdownOpen] = useState(false);
47:   const [isInstituteSwitcherOpen, setIsInstituteSwitcherOpen] = useState(false);
48:   const [searchModalOpen, setSearchModalOpen] = useState(false);
49:   const dropdownRef = useRef<HTMLDivElement>(null);
50:   const instituteSwitcherRef = useRef<HTMLDivElement>(null);
51:   const { themeMode, toggleTheme } = useTheme();
52: 
53:   const isAdmin = userRole.toUpperCase() === "ADMIN";
54: 
55:   function handleSwitchInstitute(targetCode: string) {
56:     setIsInstituteSwitcherOpen(false);
57:     setIsDropdownOpen(false);
58:     if (targetCode.toLowerCase() === instituteCode.toLowerCase()) return;
59:     const segments = pathname.split("/").filter(Boolean);
60:     if (segments.length > 0 && segments[0].toLowerCase() === instituteCode.toLowerCase()) {
61:       segments[0] = targetCode.toLowerCase();
62:       router.push("/" + segments.join("/"));
63:     } else {
64:       router.push(`/${targetCode.toLowerCase()}/admin`);
65:     }
66:   }
67: 
68:   useEffect(() => {
69:     function handleKeyDown(e: KeyboardEvent) {
70:       if ((e.metaKey || e.ctrlKey) && e.key === "k") {
71:         e.preventDefault();
72:         setSearchModalOpen((prev) => !prev);
73:       }
74:     }
75:     window.addEventListener("keydown", handleKeyDown);
76:     return () => window.removeEventListener("keydown", handleKeyDown);
77:   }, []);
78: 
79:   // Close dropdowns whenever route changes
80:   useEffect(() => {
81:     setIsDropdownOpen(false);
82:     setIsInstituteSwitcherOpen(false);
83:   }, [pathname]);
84: 
85:   useEffect(() => {
86:     function handleClickOutside(event: MouseEvent | TouchEvent) {
87:       if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
88:         setIsDropdownOpen(false);
89:       }
90:       if (instituteSwitcherRef.current && !instituteSwitcherRef.current.contains(event.target as Node)) {
91:         setIsInstituteSwitcherOpen(false);
92:       }
93:     }
94:     document.addEventListener("mousedown", handleClickOutside);
95:     document.addEventListener("touchstart", handleClickOutside, { passive: true });
96:     return () => {
97:       document.removeEventListener("mousedown", handleClickOutside);
98:       document.removeEventListener("touchstart", handleClickOutside);
99:     };
100:   }, []);
101: 
102:   async function handleLogout() {
103:     try {
104:       triggerNativeHaptic("light");
105:       logoutFromNative();
106:       await fetch("/api/auth/logout", { method: "POST" });
107:       window.location.href = `/login?institute=${instituteCode}&force=true`;
108:     } catch (error) {
109:       console.error("Logout failed", error);
110:       window.location.href = `/login?institute=${instituteCode}&force=true`;
111:     }
112:   }
113: 
114:   let dynamicTitle = "Dashboard";
115:   const segment = pathname.split("/").pop();
116: 
117:   const titleMap: Record<string, string> = {
118:     // Student
119:     students: "Student Dashboard",
120:     courses: "My Courses",
121:     announcements: "Announcements",
122:     assignments: "To-do",
123:     tasks: "Tasks",
124:     leaderboards: "Leaderboards",
125:     // Professor
126:     teachers: "Teacher Dashboard",
127:     classes: "My Classes",
128:     analytics: "Student Analytics",
129:     "create-tasks": "Create Tasks",
130:     "manage-leaderboard": "Manage Leaderboard",
131:     // Admin
132:     admin: "Admin Dashboard",
133:     accounts: "Account Management",
134:     permissions: "Permission Matrix",
135:     logs: "Audit Logs",
136:     backup: "Backup & Recovery",
137:     security: "Security Tools",
138:     // Course Management
139:     "course-management": "Course Management",
140:     stream: "Stream",
141:     classwork: "Classwork",
142:     people: "People",
143:     // Activities
144:     codelab: "CodeLab Problem Bank",
145:     instructor: "CodeLab Analytics",
146:     // Shared
147:     settings: "Settings",
148:     profile: "Profile",
149:     privacy: "Privacy Settings",
150:     "learning-materials": "Learning Materials",
151:     help: "Help & Support",
152:   };
153: 
154:   if (segment && titleMap[segment]) {
155:     dynamicTitle = titleMap[segment];
156:   }
157:   return (
158:     <header className="sticky top-0 z-50 border-b border-slate-200/80 dark:border-[rgba(255,255,255,0.07)] bg-white dark:bg-[#1A1D27] sm:bg-white/95 sm:dark:bg-[#1A1D27]/95 sm:backdrop-blur-md transition-colors duration-200 min-h-[48px] sm:min-h-[56px] flex flex-col justify-center">
159:       <div className="flex items-center justify-between gap-1.5 sm:gap-3 px-2.5 sm:px-4 lg:px-8 py-1.5 sm:py-3">
160:         {/* Left Side: Menu + Institute Badge + Dynamic Title */}
161:         <div className="flex flex-1 min-w-0 items-center gap-1.5 sm:gap-2.5">
162:           <button
163:             type="button"
164:             onClick={onOpenMobileMenu}
165:             className="rounded-lg sm:rounded-xl border border-slate-200 dark:border-[rgba(255,255,255,0.07)] p-1 sm:p-2 text-slate-700 dark:text-slate-300 lg:hidden hover:bg-slate-50 dark:hover:bg-white/5 transition-colors cursor-pointer h-8 w-8 sm:h-10 sm:w-10 flex items-center justify-center shrink-0 touch-manipulation active:scale-95"
166:             aria-label="Open menu"
167:           >
168:             <Menu className="h-4 w-4 sm:h-5 sm:w-5" />
169:           </button>
170: 
171:           {/* Mobile Institute Badge & Title */}
172:           <div className="md:hidden flex items-center gap-1.5 min-w-0 flex-1">
173:             {isAdmin ? (
174:               <div className="relative" ref={instituteSwitcherRef}>
175:                 <button
176:                   type="button"
177:                   onClick={() => setIsInstituteSwitcherOpen((prev) => !prev)}
178:                   className="px-1.5 py-0.5 rounded text-[9px] sm:text-[10px] font-black uppercase tracking-wider text-white shrink-0 shadow-xs flex items-center gap-1 active:scale-95 transition-transform"
179:                   style={{ backgroundColor: theme.colors.primary }}
180:                   aria-label="Switch institute campus"
181:                 >
182:                   {instituteCode.toUpperCase()}
183:                   <ChevronDown className={`h-2.5 w-2.5 transition-transform duration-200 ${isInstituteSwitcherOpen ? "rotate-180" : ""}`} />
184:                 </button>
185: 
186:                 {isInstituteSwitcherOpen && (
187:                   <div className="absolute left-0 top-full mt-2 w-56 rounded-2xl bg-white dark:bg-[#22263A] border border-slate-200 dark:border-white/10 p-2 shadow-2xl z-50 animate-in fade-in zoom-in-95 duration-150">
188:                     <div className="px-2.5 py-1 text-[9px] font-bold uppercase tracking-wider text-slate-400 dark:text-slate-500">
189:                       Switch Campus
190:                     </div>
191:                     <div className="space-y-1 mt-1">
192:                       {ALL_INSTITUTES.map((inst) => {
193:                         const isCurrent = inst.code.toLowerCase() === instituteCode.toLowerCase();
194:                         return (
195:                           <button
196:                             key={inst.code}
197:                             type="button"
198:                             onClick={() => handleSwitchInstitute(inst.code)}
199:                             className={`flex items-center justify-between w-full px-2.5 py-2 rounded-xl text-xs font-semibold transition-all cursor-pointer ${
200:                               isCurrent
201:                                 ? "bg-slate-100 dark:bg-white/10 text-slate-900 dark:text-white"
202:                                 : "text-slate-700 dark:text-slate-300 hover:bg-slate-50 dark:hover:bg-white/5"
203:                             }`}
204:                           >
205:                             <div className="flex items-center gap-2 min-w-0">
206:                               <span
207:                                 className="px-1.5 py-0.5 rounded text-[9px] font-black uppercase text-white shrink-0"
208:                                 style={{ backgroundColor: inst.color }}
209:                               >
210:                                 {inst.short}
211:                               </span>
212:                               <span className="truncate text-left text-xs">{inst.name}</span>
213:                             </div>
214:                             {isCurrent && <Check className="h-3.5 w-3.5 text-emerald-500 shrink-0 ml-1.5" />}
215:                           </button>
216:                         );
217:                       })}
218:                     </div>
219:                   </div>
220:                 )}
221:               </div>
222:             ) : (
223:               <span
224:                 className="px-1.5 py-0.5 rounded text-[9px] sm:text-[10px] font-black uppercase tracking-wider text-white shrink-0 shadow-xs flex items-center"
225:                 style={{ backgroundColor: theme.colors.primary }}
226:               >
227:                 {instituteCode.toUpperCase()}
228:               </span>
229:             )}
230:             <h1 className="text-xs sm:text-sm font-bold tracking-tight text-slate-900 dark:text-[#F0F2F8] truncate min-w-0 flex-1" title={dynamicTitle}>
231:               {dynamicTitle}
232:             </h1>
233:           </div>
234: 
235:           {/* Desktop & Tablet Title & Institute Badge / Switcher */}
236:           <div className="hidden md:flex items-center gap-3 min-w-0">
237:             {isAdmin ? (
238:               <div className="relative" ref={instituteSwitcherRef}>
239:                 <button
240:                   type="button"
241:                   onClick={() => setIsInstituteSwitcherOpen((prev) => !prev)}
242:                   className="flex items-center gap-2 px-2.5 py-1.5 rounded-xl border border-slate-200 dark:border-white/10 bg-slate-50/80 dark:bg-white/[0.03] hover:bg-slate-100 dark:hover:bg-white/[0.06] transition-all shadow-xs cursor-pointer text-left group"
243:                   title="Click to switch institute campus"
244:                   aria-expanded={isInstituteSwitcherOpen}
245:                 >
246:                   <span
247:                     className="px-1.5 py-0.5 rounded text-[10px] font-black uppercase tracking-wider text-white shrink-0 shadow-xs"
248:                     style={{ backgroundColor: theme.colors.primary }}
249:                   >
250:                     {instituteCode.toUpperCase()}
251:                   </span>
252:                   <div className="flex flex-col min-w-0">
253:                     <span className="text-[9px] font-semibold uppercase tracking-wider text-slate-400 dark:text-slate-500 leading-none mb-0.5 flex items-center gap-1">
254:                       Campus Switcher
255:                     </span>
256:                     <span className="text-xs font-bold text-slate-800 dark:text-[#F0F2F8] truncate max-w-[140px] lg:max-w-[200px] leading-tight">
257:                       {instituteName}
258:                     </span>
259:                   </div>
260:                   <ChevronDown className={`h-3.5 w-3.5 text-slate-400 group-hover:text-slate-600 dark:group-hover:text-slate-200 transition-transform duration-200 shrink-0 ${isInstituteSwitcherOpen ? "rotate-180" : ""}`} />
261:                 </button>
262: 
263:                 {/* Institute Switcher Dropdown */}
264:                 {isInstituteSwitcherOpen && (
265:                   <div className="absolute left-0 mt-2 w-72 rounded-2xl bg-white dark:bg-[#22263A] border border-slate-200 dark:border-white/10 p-2.5 shadow-2xl z-50 animate-in fade-in zoom-in-95 duration-150">
266:                     <div className="px-2 py-1 text-[10px] font-bold uppercase tracking-wider text-slate-400 dark:text-slate-500 flex items-center gap-1.5">
267:                       <Building2 className="h-3 w-3" />
268:                       Switch Campus Portal
269:                     </div>
270:                     <div className="space-y-1 mt-1.5">
271:                       {ALL_INSTITUTES.map((inst) => {
272:                         const isCurrent = inst.code.toLowerCase() === instituteCode.toLowerCase();
273:                         return (
274:                           <button
275:                             key={inst.code}
276:                             type="button"
277:                             onClick={() => handleSwitchInstitute(inst.code)}
278:                             className={`flex items-center justify-between w-full px-2.5 py-2 rounded-xl text-xs font-semibold transition-all cursor-pointer ${
279:                               isCurrent
