1: import { db } from "./db";
2: import { cookies, headers } from "next/headers";
3: import crypto from "crypto";
4: 
5: /**
6:  * Computes a SHA-256 digest of an opaque bearer token.
7:  * Only this hash is stored and looked up in the database.
8:  */
9: export function hashToken(token: string): string {
10:   return crypto.createHash("sha256").update(token).digest("hex");
11: }
12: 
13: export interface CreateSessionResult {
14:   sessionId: string;
15:   token: string;
16:   expiresAt: Date;
17: }
18: 
19: /**
20:  * Creates a real database-backed session for the user using a 256-bit CSPRNG opaque token.
21:  * Returns the raw token for client credentials while storing only the SHA-256 hash in PostgreSQL.
22:  */
23: export async function createSession(
24:   userId: string,
25:   metadata?: { userAgent?: string; ipAddress?: string }
26: ): Promise<CreateSessionResult> {
27:   // 7-day session validity
28:   const expiresAt = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000);
29: 
30:   // Generate 256 bits of cryptographic entropy
31:   const rawToken = crypto.randomBytes(32).toString("base64url");
32:   const tokenHash = hashToken(rawToken);
33: 
34:   const session = await db.session.create({
35:     data: {
36:       tokenHash,
37:       userId,
38:       expiresAt,
39:       userAgent: metadata?.userAgent,
40:       ipAddress: metadata?.ipAddress,
41:     },
42:   });
43: 
44:   const cookieStore = await cookies();
45:   cookieStore.set("lumina_session", rawToken, {
46:     httpOnly: true,
47:     secure: process.env.NODE_ENV === "production",
48:     sameSite: "lax",
49:     expires: expiresAt,
50:     path: "/",
51:   });
52: 
53:   return {
54:     sessionId: session.id,
55:     token: rawToken,
56:     expiresAt,
57:   };
58: }
59: 
60: /**
61:  * Validates the session from the lumina_session cookie or Authorization: Bearer header.
62:  * Hashes the incoming opaque token and verifies matching session in the database.
63:  * If expired or invalid, clears the cookie (if present) and returns null.
64:  */
65: export async function getSession() {
66:   let rawToken: string | undefined;
67:   let isCookie = false;
68: 
69:   try {
70:     const cookieStore = await cookies();
71:     rawToken = cookieStore.get("lumina_session")?.value;
72:     if (rawToken) {
73:       isCookie = true;
74:     }
75:   } catch {
76:     // cookies() might throw in non-request contexts
77:   }
78: 
79:   if (!rawToken) {
80:     try {
81:       const headerStore = await headers();
82:       const authHeader = headerStore.get("authorization");
83:       if (authHeader?.startsWith("Bearer ")) {
84:         rawToken = authHeader.slice(7).trim();
85:       }
86:     } catch {
87:       // headers() might throw in non-request contexts
88:     }
89:   }
90: 
91:   if (!rawToken) return null;
92: 
93:   try {
94:     const tokenHash = hashToken(rawToken);
95: 
96:     // Look up session by tokenHash (or fallback to id for transition backwards-compatibility)
97:     const session = await db.session.findFirst({
98:       where: {
99:         OR: [{ tokenHash }, { id: rawToken }],
100:       },
101:       include: {
102:         user: {
103:           include: { institute: true },
104:         },
105:       },
106:     });
107: 
108:     if (!session) {
109:       return null;
110:     }
111: 
112:     if (session.expiresAt.getTime() < Date.now()) {
113:       // Session expired, purge from database
114:       await db.session.delete({ where: { id: session.id } }).catch(() => {});
115:       if (isCookie) {
116:         try {
117:           const cookieStore = await cookies();
118:           cookieStore.delete("lumina_session");
119:         } catch {}
120:       }
121:       return null;
122:     }
123: 
124:     // Check if user account is active
125:     const user = session.user as Record<string, unknown>;
126:     if (user.isActive === false) {
127:       // Purge session for deactivated user
128:       await db.session.delete({ where: { id: session.id } }).catch(() => {});
129:       if (isCookie) {
130:         try {
131:           const cookieStore = await cookies();
132:           cookieStore.delete("lumina_session");
133:         } catch {}
134:       }
135:       return null;
136:     }
137: 
138:     return session;
139:   } catch (error) {
140:     console.error("Session lookup error", error);
141:     return null;
142:   }
143: }
144: 
145: /**
146:  * Deletes the session from the database and clears the lumina_session cookie.
147:  * Accepts optional tokenOverride for Bearer tokens sent from mobile/desktop clients.
148:  */
149: export async function deleteSession(tokenOverride?: string) {
150:   let rawToken = tokenOverride;
151: 
152:   try {
153:     const cookieStore = await cookies();
154:     if (!rawToken) {
155:       rawToken = cookieStore.get("lumina_session")?.value;
156:     }
157:     cookieStore.delete("lumina_session");
158:   } catch {
159:     // Non-cookie environment
160:   }
161: 
162:   if (rawToken) {
163:     try {
164:       const tokenHash = hashToken(rawToken);
165:       // Delete matching session by tokenHash or id in a single query
166:       await db.session.deleteMany({
167:         where: {
168:           OR: [{ tokenHash }, { id: rawToken }],
169:         },
170:       });
171:     } catch (error) {
172:       console.error("Error deleting session from DB:", error);
173:     }
174:   }
175: }
