1: import { PrismaPg } from "@prisma/adapter-pg";
2: import { PrismaClient } from "@prisma/client";
3: import { Pool, type PoolConfig } from "pg";
4: 
5: const globalForPrisma = globalThis as unknown as {
6:   prisma?: PrismaClient;
7:   pgPool?: Pool;
8: };
9: 
10: const createPrismaClient = () => {
11:   // Support standard DATABASE_URL as well as Vercel Postgres / Neon integration variables
12:   const connectionString =
13:     process.env.DATABASE_URL ||
14:     process.env.POSTGRES_PRISMA_URL ||
15:     process.env.POSTGRES_URL;
16: 
17:   if (!connectionString) {
18:     throw new Error(
19:       "[Database Error] No database connection string found. Please set DATABASE_URL (or POSTGRES_PRISMA_URL / POSTGRES_URL) in your environment variables (e.g. in Vercel Project Settings > Environment Variables)."
20:     );
21:   }
22: 
23:   if (!globalForPrisma.pgPool) {
24:     const isProduction = process.env.NODE_ENV === "production";
25:     const isLocalhost =
26:       connectionString.includes("localhost") ||
27:       connectionString.includes("127.0.0.1") ||
28:       connectionString.includes("::1");
29: 
30:     const poolConfig: PoolConfig = {
31:       connectionString,
32:       // In serverless production (e.g. Vercel), limit connections per lambda to prevent pool exhaustion
33:       max: isProduction ? 2 : 10,
34:       idleTimeoutMillis: 30000,
35:       connectionTimeoutMillis: 15000,
36:       keepAlive: true,
37:       // Cloud databases (Supabase, Neon, AWS RDS, Railway, Render) require SSL.
38:       // rejectUnauthorized: false prevents "self-signed certificate in certificate chain" errors
39:       ssl: !isLocalhost ? { rejectUnauthorized: false } : undefined,
40:     };
41: 
42:     globalForPrisma.pgPool = new Pool(poolConfig);
43: 
44:     // Handle unexpected idle connection resets gracefully (common with serverless poolers)
45:     globalForPrisma.pgPool.on("error", (err) => {
46:       console.warn("PG Pool idle connection notice:", err.message);
47:     });
48:   }
49: 
50:   const adapter = new PrismaPg(globalForPrisma.pgPool);
51:   return new PrismaClient({
52:     adapter,
53:     log: process.env.NODE_ENV === "development" ? ["error", "warn"] : ["error"],
54:   });
55: };
56: 
57: export const db = globalForPrisma.prisma ?? createPrismaClient();
58: 
59: // Always cache client on globalThis in all environments so warm serverless lambdas reuse the instance
60: globalForPrisma.prisma = db;
61: 
62:

apps/web/src/lib/kx-eligibility.ts.numberedContent:
1: /**
2:  * apps/web/src/lib/kx-eligibility.ts
3:  *
4:  * Single source of truth for determining whether a user can access
5:  * the Knowledge Exchange (KX) Q&A module.
6:  *
7:  * RULE: Strictly gated to users belonging to the Institute of Computer Studies (ICS).
8:  * Non-ICS institutes (e.g. IBE, ITE) are barred from access.
9:  */
10: 
11: import { db } from "./db";
12: import { getSession } from "./auth-session";
13: import { getSessionFromRequest } from "./api-auth";
14: import { normalizeRole } from "./admin-types";
15: 
16: /** The institute code that gates access to Knowledge Exchange. */
17: export const ELIGIBLE_KX_INSTITUTE_CODE = "ics";
18: 
19: /**
20:  * Minimal session shape needed for eligibility checks.
21:  */
22: export interface KxEligibilitySession {
23:   user: {
24:     id?: string;
25:     role?: string;
26:     instituteId?: string;
27:   };
28: }
29: 
30: /**
31:  * Synchronous check for whether an institute code is eligible for KX.
32:  *
33:  * @param instituteCode Institute code string (e.g., "ics", "ibe", "ite")
34:  * @returns true if code is "ics", false otherwise
35:  */
36: export function isEligibleKxInstituteCode(instituteCode?: string | null): boolean {
37:   if (!instituteCode || typeof instituteCode !== "string") return false;
38:   return instituteCode.toLowerCase() === ELIGIBLE_KX_INSTITUTE_CODE;
39: }
40: 
41: /**
42:  * Checks if a user session or institute code is eligible for Knowledge Exchange.
43:  * Overloaded to accept an institute code string or a session object.
44:  *
45:  * @param target Institute code string or user session
46:  * @returns boolean or Promise<boolean>
47:  */
48: export function isEligibleForKnowledgeExchange(instituteCode: string): boolean;
49: export function isEligibleForKnowledgeExchange(session: KxEligibilitySession): Promise<boolean>;
50: export function isEligibleForKnowledgeExchange(
51:   target: string | KxEligibilitySession | null | undefined
52: ): boolean | Promise<boolean> {
53:   if (!target) return false;
54: 
55:   if (typeof target === "string") {
56:     return isEligibleKxInstituteCode(target);
57:   }
58: 
59:   return (async () => {
60:     if (!target.user?.instituteId) return false;
61: 
62:     try {
63:       const institute = await db.institute.findUnique({
64:         where: { id: target.user.instituteId },
65:         select: { code: true },
66:       });
67: 
68:       if (!institute?.code) return false;
69:       return isEligibleKxInstituteCode(institute.code);
70:     } catch {
71:       return false;
72:     }
73:   })();
74: }
75: 
76: /**
77:  * Full eligibility check for API route handlers and server actions.
78:  * Resolves session, checks institute, and returns structured result.
79:  *
80:  * @param request Optional request for mobile Bearer token resolution
81:  * @returns Eligibility result and session, or null if unauthenticated
82:  */
83: export async function checkKxEligibility(request?: Request) {
84:   let session = request ? await getSessionFromRequest(request) : await getSession();
85:   if (!session && !request) {
86:     // Fallback try request if not passed
87:     session = await getSession();
88:   }
89: 
90:   if (!session) {
91:     return null;
92:   }
93: 
94:   const role = normalizeRole(session.user.role as string);
95: 
96:   if (request) {
97:     const headerCode = request.headers.get("x-institute-code");
98:     if (headerCode && !isEligibleKxInstituteCode(headerCode)) {
99:       return {
100:         eligible: false,
101:         session,
102:         role,
103:         instituteCode: headerCode.toLowerCase(),
104:       };
105:     }
106: 
107:     try {
108:       const url = new URL(request.url);
109:       const queryInstitute = url.searchParams.get("institute");
110:       if (queryInstitute && !isEligibleKxInstituteCode(queryInstitute)) {
111:         return {
112:           eligible: false,
113:           session,
114:           role,
115:           instituteCode: queryInstitute.toLowerCase(),
116:         };
117:       }
118:     } catch {
119:       // Ignore URL parsing errors
120:     }
121:   }
122: 
123:   let instituteCode = "";
124:   if (session.user.instituteId) {
125:     const institute = await db.institute.findUnique({
126:       where: { id: session.user.instituteId },
127:       select: { code: true },
128:     });
129:     if (institute?.code) {
130:       instituteCode = institute.code.toLowerCase();
131:     }
132:   }
133: 
134:   const eligible = isEligibleKxInstituteCode(instituteCode);
135: 
136:   return {
137:     eligible,
138:     session,
139:     role,
140:     instituteCode,
141:   };
142: }
143:

apps/web/src/lib/rbac.ts.numberedContent:
1: /**
2:  * Role-Based Access Control (RBAC) Module
3:  *
4:  * Provides permission checking, role normalization, session guards,
5:  * and re-authentication utilities for the admin system.
6:  */
7: 
8: import { db } from './db';
9: import { getSession } from './auth-session';
10: import { compare } from 'bcryptjs';
11: import {
12:   normalizeRole,
13:   DEFAULT_ROLE_PERMISSIONS,
14:   type UserRole,
15:   type SystemPermission,
16: } from './admin-types';
17: 
18: // Re-export for convenience
19: export { normalizeRole } from './admin-types';
20: 
21: // ─── Permission Helpers ───
22: 
23: /**
24:  * Parses the JSON permissions string stored in the database.
25:  * Returns an empty array on parse failure.
26:  */
27: export function parsePermissions(raw: string): string[] {
28:   try {
29:     const parsed = JSON.parse(raw);
30:     return Array.isArray(parsed) ? parsed : [];
31:   } catch {
32:     return [];
33:   }
34: }
35: 
36: /**
37:  * Checks if a user's permission array includes the required permission.
38:  */
39: export function hasPermission(
40:   permissions: string[],
41:   required: SystemPermission
42: ): boolean {
43:   return permissions.includes(required);
44: }
45: 
46: /**
47:  * Returns the default permission set for a given role.
48:  */
49: export function getDefaultPermissions(role: UserRole): SystemPermission[] {
50:   return DEFAULT_ROLE_PERMISSIONS[role] ?? [];
51: }
52: 
53: // ─── Session Guards ───
54: 
55: export interface AdminSession {
56:   sessionId: string;
57:   user: {
58:     id: string;
59:     name: string;
60:     email: string;
61:     role: string;
62:     isActive: boolean;
63:     permissions: string;
64:     instituteId: string;
65:   };
66: }
67: 
68: /**
69:  * Validates the current session and returns it.
70:  * Returns null if no valid session exists.
71:  */
72: export async function getValidSession(): Promise<AdminSession | null> {
73:   const session = await getSession();
74:   if (!session) return null;
75: 
76:   return {
77:     sessionId: session.id,
78:     user: {
79:       id: session.user.id,
80:       name: session.user.name,
81:       email: session.user.email,
82:       role: session.user.role,
83:       isActive: (session.user as Record<string, unknown>).isActive !== false,
84:       permissions: ((session.user as Record<string, unknown>).permissions as string) ?? '[]',
85:       instituteId: session.user.instituteId,
86:     },
87:   };
88: }
89: 
90: /**
91:  * Requires the current user to be an authenticated ADMIN.
92:  * Returns the session or throws a Response-compatible error object.
93:  */
94: export async function requireAdmin(): Promise<AdminSession> {
95:   const session = await getValidSession();
96: 
97:   if (!session) {
98:     throw { status: 401, message: 'Authentication required.' };
99:   }
100: 
101:   const role = normalizeRole(session.user.role);
102:   if (role !== 'ADMIN') {
103:     throw { status: 403, message: 'Forbidden: Admin access required.' };
104:   }
105: 
106:   if (!session.user.isActive) {
107:     throw { status: 403, message: 'Your account has been deactivated. Please contact administration.' };
108:   }
109: 
110:   return session;
111: }
112: 
113: /**
114:  * Requires the current user to have a specific permission.
115:  */
116: export async function requirePermission(
117:   permission: SystemPermission
118: ): Promise<AdminSession> {
119:   const session = await getValidSession();
120: 
121:   if (!session) {
122:     throw { status: 401, message: 'Authentication required.' };
123:   }
124: 
125:   if (!session.user.isActive) {
126:     throw { status: 403, message: 'Your account has been deactivated. Please contact administration.' };
127:   }
128: 
129:   const role = normalizeRole(session.user.role);
130:   if (role === 'ADMIN') return session; // Admins always pass
131: 
132:   const userPermissions = parsePermissions(session.user.permissions);
133:   if (!hasPermission(userPermissions, permission)) {
134:     throw { status: 403, message: `Forbidden: Missing permission '${permission}'.` };
135:   }
136: 
137:   return session;
138: }
139: 
140: /**
141:  * Re-authentication check for sensitive operations (e.g., role changes).
142:  * Requires the admin to provide their current password.
143:  */
144: export async function requireReAuth(
145:   adminId: string,
146:   password: string
147: ): Promise<boolean> {
148:   const admin = await db.user.findUnique({
149:     where: { id: adminId },
150:     select: { password: true },
151:   });
152: 
153:   if (!admin) {
154:     throw { status: 404, message: 'Admin user not found.' };
155:   }
156: 
157:   const valid = await compare(password, admin.password);
158:   if (!valid) {
159:     throw { status: 401, message: 'Re-authentication failed. Incorrect password.' };
160:   }
161: 
162:   return true;
163: }
164: 
165: // ─── Audit Logging ───
166: 
167: /**
168:  * Creates an immutable audit log entry.
169:  */
170: export async function createAuditLog(params: {
171:   adminId: string;
172:   targetId: string;
173:   action: string;
174:   ipAddress?: string;
175:   metadata?: Record<string, unknown>;
176: }): Promise<void> {
177:   await db.auditLog.create({
178:     data: {
179:       adminId: params.adminId,
180:       targetId: params.targetId,
181:       action: params.action,
182:       ipAddress: params.ipAddress ?? '',
183:       metadata: params.metadata ? JSON.stringify(params.metadata) : '{}',
184:     },
185:   });
186: }
187: 
188: /**
189:  * Extracts the client IP address from request headers.
190:  */
191: export function getClientIp(request: Request): string {
192:   const forwarded = request.headers.get('x-forwarded-for');
193:   if (forwarded) {
194:     return forwarded.split(',')[0].trim();
195:   }
196:   const realIp = request.headers.get('x-real-ip');
197:   return realIp ?? '127.0.0.1';
198: }
199:

apps/web/src/middleware.ts.numberedContent:
1: import { NextResponse } from "next/server";
2: import type { NextRequest } from "next/server";
3: import { getSecurityHeaders } from "@/lib/security-headers";
4: import { getCorsHeaders } from "@/lib/cors";
5: 
6: // Known static file extensions to safely skip page-level redirects
7: const STATIC_EXTENSION_REGEX = /\.(ico|png|jpg|jpeg|svg|css|js|woff|woff2|ttf|eot|webp|json|map|txt|xml)$/i;
8: 
9: export async function middleware(request: NextRequest) {
10:   const pathname = request.nextUrl.pathname;
11:   const securityHeaders = getSecurityHeaders();
12:   const corsHeaders = getCorsHeaders(request);
13: 
14:   // Exclude static assets and _next internals
15:   if (
16:     STATIC_EXTENSION_REGEX.test(pathname) ||
17:     pathname.startsWith("/_next")
18:   ) {
19:     return NextResponse.next();
20:   }
21: 
22:   // Handle API routes: apply security and CORS headers, then pass to API route handlers
23:   if (pathname.startsWith("/api")) {
24:     const response = NextResponse.next();
25:     for (const [key, value] of Object.entries(securityHeaders)) {
26:       response.headers.set(key, value);
27:     }
28:     for (const [key, value] of Object.entries(corsHeaders)) {
29:       response.headers.set(key, value);
30:     }
31:     return response;
32:   }
33: 
34:   // Session token presence check (web cookie)
35:   const token = request.cookies.get("lumina_session")?.value;
36: 
37:   // Public routes allowlist (no session needed)
38:   const isPublicRoute =
39:     pathname === "/" ||
40:     pathname === "/login" ||
41:     pathname === "/register" ||
42:     pathname === "/forgot-password" ||
43:     pathname === "/reset-password";
44: 
45:   if (!isPublicRoute && !token) {
46:     // Extract institute slug dynamically from path (e.g., /ics/courses -> ics)
47:     const segments = pathname.split("/").filter(Boolean);
48:     const possibleInstitute = segments[0] || "ics";
49: 
50:     const loginUrl = new URL(`/login?institute=${encodeURIComponent(possibleInstitute)}`, request.url);
51:     const redirectResponse = NextResponse.redirect(loginUrl);
52: 
53:     for (const [key, value] of Object.entries(securityHeaders)) {
54:       redirectResponse.headers.set(key, value);
55:     }
56:     return redirectResponse;
57:   }
58: 
59:   // Standard response with security headers
60:   const response = NextResponse.next();
61:   for (const [key, value] of Object.entries(securityHeaders)) {
62:     response.headers.set(key, value);
63:   }
64:   for (const [key, value] of Object.entries(corsHeaders)) {
65:     response.headers.set(key, value);
66:   }
67: 
68:   return response;
69: }
70: 
71: export const config = {
72:   matcher: [
73:     /*
74:      * Match all request paths except for static files:
75:      * - _next/static (static files)
76:      * - _next/image (image optimization files)
77:      * - favicon.ico, sitemap.xml, robots.txt (metadata files)
78:      */
79:     "/((?!_next/static|_next/image|favicon.ico|sitemap.xml|robots.txt).*)",
80:   ],
81: };
82:
